g=grid
from collections import Counter, deque
H,W=len(g),len(g[0])
majors={8,7,4}
# flood fill noise cells: assign to adjacent major cell's color, BFS
out=[r[:] for r in g]
q=deque()
region=[[None]*W for _ in range(H)]
for i in range(H):
    for j in range(W):
        if g[i][j] in majors:
            region[i][j]=g[i][j]; q.append((i,j))
noise={(i,j) for i in range(H) for j in range(W) if g[i][j] not in majors}
while noise:
    i,j=q.popleft()
    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
        ni,nj=i+di,j+dj
        if 0<=ni<H and 0<=nj<W and (ni,nj) in noise:
            region[ni][nj]=region[i][j]; noise.discard((ni,nj)); q.append((ni,nj))
print(len(noise))
for i in range(H):
    print(' '.join(str(region[i][j]) for j in range(W)))
